<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { ElButton, ElAlert, ElDialog } from 'element-plus'
import { callAdmin } from './api'
type Row = { _id: string; adminId: string; action: string; target: string; detail: Record<string, unknown>; username: string; success: boolean; reason: string; createdAt: string }
const admins = ref<{ _id: string; username: string }[]>([]), rows = ref<Row[]>([]), kind = ref('actions'), page = ref(0), more = ref(false), busy = ref(false), error = ref(''), operation = ref(''), target = ref(''), adminId = ref(''), username = ref(''), from = ref(''), to = ref(''), selected = ref<Row>()
const names: Record<string, string> = { 'member.balance': '手动调整余额', 'order.refund.approve': '退款通过', 'order.refund.reject': '退款驳回', 'order.ship': '订单发货', 'refund.approve': '按件退款通过', 'refund.reject': '按件退款驳回', 'catalog.shelf': '商品上下架', 'catalog.stock': '商品库存调整', 'catalog.save': '商品保存', 'catalog.complete': '商品完成上新', 'catalog.approve': '商品审核通过', 'catalog.reject': '商品审核打回', 'catalog.category.save': '分类保存', 'catalog.category.delete': '分类删除', 'catalog.clearDemo': '清空演示数据', 'membership.config.save': '会员设置保存', 'membership.tier.save': '会员档位保存', 'membership.tier.delete': '会员档位删除', 'membership.setLevel': '会员手动定级', 'freight.save': '运费模板保存', 'freight.delete': '运费模板删除', 'faq.save': 'FAQ保存', 'faq.delete': 'FAQ删除', 'system.save': '系统设置保存', 'system.shopConfig': '店铺配置保存', 'home.banner.save': '轮播保存', 'home.banner.delete': '轮播删除', 'home.pick.save': '主推保存', 'home.pick.delete': '主推删除', 'home.announcement.save': '公告保存', 'home.announcement.delete': '公告删除', 'home.interval': '公告间隔保存', 'home.splash.save': '开屏保存' }
const money = (v: unknown) => (Number(v || 0) / 100).toFixed(2)
Object.assign(names, { 'changePassword': '管理员改密' })
const loginReasons: Record<string, string> = { LOGIN_OK: '登录成功', INVALID_CREDENTIALS: '账号或密码错误', ACCOUNT_LOCKED: '账号已锁定' }
function summary(row: Row) {
  const d = row.detail || {}
  if (row.action === 'member.balance') return `调整 ¥${money(d.amount)}；余额 ¥${money(d.balanceBefore)} → ¥${money(d.balanceAfter)}；理由：${d.reason}`
  if (row.action === 'order.refund.approve') return `${Number(d.balanceAmount) > 0 ? `余额退 ¥${money(d.balanceAmount)}；` : ''}原路退 ¥${money(d.originalAmount)}；${d.originalStatus === 'pending_simulated' ? '原路待退（模拟）' : '无原路待退'}`
  if (row.action === 'order.refund.reject') return `理由：${d.reason}`
  if (row.action === 'catalog.shelf') return d.onShelf ? '上架' : '下架'
  if (row.action === 'order.ship') return `${d.company} · ${d.tracking}`
  if (row.action === 'catalog.stock') return `库存增减 ${d.delta}`
  return '配置或状态变更，展开查看记录'
}
async function run(fn: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; try { await fn() } catch (e) { error.value = e instanceof Error ? e.message : '查询失败' } finally { busy.value = false } }
async function load() { const r = await callAdmin<{ rows: Row[]; hasMore: boolean }>('audit.list', { kind: kind.value, page: page.value, operation: operation.value, target: target.value, adminId: adminId.value, username: username.value, from: from.value ? new Date(from.value + 'T00:00:00+08:00').toISOString() : undefined, to: to.value ? new Date(to.value + 'T23:59:59.999+08:00').toISOString() : undefined }); rows.value = r.rows; more.value = r.hasMore }
function search() { run(async () => { page.value = 0; await load() }) }
function next(delta: number) { run(async () => { page.value += delta; await load() }) }
onMounted(() => run(async () => { admins.value = (await callAdmin<{ admins: typeof admins.value }>('audit.meta')).admins; await load() }))
</script>
<template><section class="content audit-manager"><div class="section-heading"><div><p class="eyebrow">OPERATION HISTORY</p><h1>操作留痕</h1></div></div><ElAlert v-if="error" :title="error" type="error" :closable="false"/><form class="admin-form settings-card" @submit.prevent="search"><div class="settings-grid"><label>记录类型<select v-model="kind" aria-label="留痕记录类型" :disabled="busy"><option value="actions">后台操作</option><option value="login">管理员登录</option></select></label><template v-if="kind==='actions'"><label>操作类型<select v-model="operation" aria-label="留痕操作类型" :disabled="busy"><option value="">全部操作</option><option v-for="(name,key) in names" :key="key" :value="key">{{name}}</option></select></label><label>对象编号<input v-model="target" aria-label="留痕对象编号" placeholder="订单、会员或商品编号" maxlength="120" :disabled="busy"/></label><label>操作人<select v-model="adminId" aria-label="留痕操作人" :disabled="busy"><option value="">全部管理员</option><option v-for="a in admins" :key="a._id" :value="a._id">{{a.username}}</option></select></label></template><label v-else>登录账号<input v-model="username" aria-label="登录日志账号" maxlength="80" :disabled="busy"/></label><label>开始日期（上海时间）<input v-model="from" aria-label="留痕开始日期" type="date" :disabled="busy"/></label><label>结束日期（上海时间）<input v-model="to" aria-label="留痕结束日期" type="date" :disabled="busy"/></label></div><ElButton native-type="submit" type="primary" :loading="busy">查询留痕</ElButton></form><p class="muted">记录只读，每页50条；余额、退款与关键状态变更和业务写入同事务留痕。</p><article v-for="row in rows" :key="row._id" class="settings-card audit-card" :data-audit-id="row._id"><template v-if="kind==='actions'"><h3>{{names[row.action]||'其他后台操作'}}</h3><p class="order-id">对象 {{row.target||'—'}}</p><p>{{summary(row)}}</p><p class="muted">{{admins.find(a=>a._id===row.adminId)?.username||row.adminId}} · {{new Date(row.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</p><ElButton @click="selected=row">查看变更记录</ElButton></template><template v-else><h3>{{row.username||'未提供账号'}} · {{row.success?'登录成功':'登录拒绝'}}</h3><p>{{loginReasons[row.reason]||row.reason}}</p><p class="muted">{{new Date(row.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</p></template></article><p v-if="!rows.length">没有匹配记录</p><div class="action-row audit-pagination"><ElButton :disabled="page===0||busy" @click="next(-1)">上一页记录</ElButton><span>第 {{page+1}} 页</span><ElButton :disabled="!more||busy" @click="next(1)">下一页记录</ElButton></div><ElDialog :model-value="!!selected" @close="selected=undefined" title="变更记录详情" width="min(700px, calc(100vw - 24px))"><template v-if="selected"><h3>{{names[selected.action]||selected.action}}</h3><p class="order-id">记录 {{selected._id}}<br>对象 {{selected.target}}</p><p>{{summary(selected)}}</p><details><summary>完整变更数据</summary><pre class="audit-json">{{JSON.stringify(selected.detail,null,2)}}</pre></details><p class="muted">原始记录仅供核对，不可修改或删除。</p></template></ElDialog></section></template>
<style>.audit-card{overflow-wrap:anywhere}.audit-json{white-space:pre-wrap;overflow-wrap:anywhere;background:#f3f5f9;padding:16px;font-size:12px;line-height:1.7}.audit-pagination{justify-content:center;align-items:center;margin:24px 0}.audit-card h3{line-height:1.7}@media(max-width:768px){.audit-manager .section-heading h1{font-size:26px}}</style>
